const KB_ROOT = '/home/node/.n8n-files/Uranus/knowledge/cole-medin-knowledge-base';
const SOURCE_ROOT = 'knowledge/cole-medin-knowledge-base';
const EXACT_QUESTION = 'What does Cole mean when he says an LLM gets into “the dumb zone”?';
const MAX_BYTES = 131072;
const route = [
  { kb_path: 'concepts/context-rot.md', role: 'canonical_concept' },
  { kb_path: 'sources/are-agent-harnesses-bringing-back-vibe-coding.md', role: 'linked_source' },
];
const input = $input.first().json;
if (typeof input.question !== 'string' || input.question !== EXACT_QUESTION) {
  return [{ json: {
    status: 'error',
    error_code: 'PILOT_QUESTION_MISMATCH',
    message: 'This one-question pilot accepts only the exact frozen Q4 question.',
    expected_question: EXACT_QUESTION,
    received_question: typeof input.question === 'string' ? input.question : null,
    _route_ready: false,
  } }];
}
return route.map((entry, route_index) => ({ json: {
  status: 'validated',
  question: EXACT_QUESTION,
  selection_method: 'frozen_index_and_link_route',
  route_index,
  role: entry.role,
  kb_path: entry.kb_path,
  source_path: `${SOURCE_ROOT}/${entry.kb_path}`,
  absolute_path: `${KB_ROOT}/${entry.kb_path}`,
  max_bytes: MAX_BYTES,
  _route_ready: true,
} }));

const KB_ROOT = '/home/node/.n8n-files/Uranus/knowledge/cole-medin-knowledge-base';
const manifest = $('Validate exact Q4 and emit frozen route').all().map((item) => item.json);
const items = $input.all();
function fail(errorCode, message) {
  return [{ json: { status: 'error', error_code: errorCode, message, _can_extract: false } }];
}
if (manifest.length !== 2 || manifest.some((entry) => entry.status !== 'validated')) {
  return fail('INVALID_ROUTE_MANIFEST', 'The frozen Q4 route manifest is incomplete.');
}
if (items.length !== manifest.length || items.some((item) => typeof item.json.error === 'string')) {
  return fail('ROUTE_READ_FAILED', 'Every frozen canonical page must be read successfully before packet assembly.');
}
const expectedByAbsolutePath = new Map(manifest.map((entry) => [entry.absolute_path, entry]));
const seen = new Set();
const prepared = [];
for (const item of items) {
  const binary = item.binary?.data;
  const bytes = Number(binary?.bytes);
  const directory = typeof binary?.directory === 'string' ? binary.directory.split(String.fromCharCode(92)).join('/') : '';
  const fileName = typeof binary?.fileName === 'string' ? binary.fileName : '';
  if (!binary || !Number.isSafeInteger(bytes) || bytes < 0 || !directory || !fileName) {
    return fail('ROUTE_READ_FAILED', 'A frozen route page did not return trustworthy path or size metadata.');
  }
  const absolutePath = `${directory.replace(/[/]+$/, '')}/${fileName}`;
  if (!absolutePath.startsWith(`${KB_ROOT}/`)) {
    return fail('ROUTE_SCOPE_VIOLATION', 'A frozen route page resolved outside the Uranus Cole KB root.');
  }
  const expected = expectedByAbsolutePath.get(absolutePath);
  if (!expected || seen.has(absolutePath)) {
    return fail('ROUTE_SCOPE_VIOLATION', 'The file read did not match the unique frozen route manifest.');
  }
  if (bytes > expected.max_bytes) {
    return fail('PAGE_TOO_LARGE', `A frozen route page exceeds the ${expected.max_bytes}-byte limit.`);
  }
  seen.add(absolutePath);
  prepared.push({ json: { ...expected, status: 'ready', content_bytes: bytes, _can_extract: true }, binary: item.binary });
}
if (seen.size !== manifest.length) return fail('ROUTE_READ_FAILED', 'A frozen route page is missing.');
prepared.sort((left, right) => left.json.route_index - right.json.route_index);
return prepared;

const EXPECTED_QUESTION = 'What does Cole mean when he says an LLM gets into “the dumb zone”?';
const EXPECTED_PATHS = [
  'concepts/context-rot.md',
  'sources/are-agent-harnesses-bringing-back-vibe-coding.md',
];
const MAX_PAGES = 2;
const MAX_EXCERPT_CHARS_PER_PAGE = 5000;
const MAX_PACKET_CHARS = 10000;
function fail(errorCode, message) {
  return [{ json: { status: 'error', error_code: errorCode, message, _packet_ready: false } }];
}
function bodyWithoutFrontmatter(content) {
  if (!content.startsWith('---')) return content.trim();
  const marker = content.indexOf('\n---', 3);
  if (marker === -1) return '';
  const after = content.indexOf('\n', marker + 4);
  return after === -1 ? '' : content.slice(after + 1).trim();
}
function beforeHeading(body, heading) {
  const at = body.indexOf(`\n${heading}`);
  return (at === -1 ? body : body.slice(0, at)).trim();
}
const items = $input.all();
if (items.length !== MAX_PAGES) return fail('PACKET_ROUTE_MISMATCH', 'The packet requires exactly two decoded canonical pages.');
const byPath = new Map();
for (const item of items) {
  const current = item.json;
  if (typeof current.error === 'string' || typeof current.content !== 'string') return fail('DECODE_FAILED', 'A frozen route page could not be decoded as UTF-8.');
  if (current.content.includes('�')) return fail('INVALID_UTF8', 'A frozen route page contains invalid UTF-8 byte sequences.');
  if (!EXPECTED_PATHS.includes(current.kb_path) || byPath.has(current.kb_path)) return fail('PACKET_ROUTE_MISMATCH', 'Decoded pages do not match the unique frozen evidence route.');
  byPath.set(current.kb_path, current);
}
if (EXPECTED_PATHS.some((path) => !byPath.has(path))) return fail('PACKET_ROUTE_MISMATCH', 'A required frozen evidence page is missing.');
const concept = byPath.get(EXPECTED_PATHS[0]);
const conceptBody = bodyWithoutFrontmatter(concept.content);
const conceptCore = beforeHeading(conceptBody, '## Contrasts with');
const sourceLinkLine = conceptBody.split(/\r?\n/).find((line) => line.includes('(../sources/are-agent-harnesses-bringing-back-vibe-coding.md)'));
if (!conceptCore.includes('gets into the dumb zone') || !sourceLinkLine) return fail('PROVENANCE_MISSING', 'The concept page no longer contains the frozen Q4 claim and linked source evidence.');
const conceptExcerpt = `${conceptCore}\n\n## Linked source evidence\n\n${sourceLinkLine}`;
const source = byPath.get(EXPECTED_PATHS[1]);
const sourceBody = bodyWithoutFrontmatter(source.content);
const sourceSummary = beforeHeading(sourceBody, '## Concepts covered');
const keyMomentLine = sourceBody.split(/\r?\n/).find((line) => line.includes('**[0:19:21]**'));
if (!sourceSummary || !keyMomentLine || !sourceSummary.toLowerCase().includes('bounded attention')) return fail('PROVENANCE_MISSING', 'The linked source no longer contains the frozen Q4 summary and key moment.');
const sourceExcerpt = `${sourceSummary}\n\n## Key moment\n\n${keyMomentLine}`;
const evidence = [
  {
    kb_path: concept.kb_path,
    source_path: concept.source_path,
    heading: 'Context Rot',
    role: 'canonical_concept',
    excerpt: conceptExcerpt,
    linked_sources: [source.kb_path],
  },
  {
    kb_path: source.kb_path,
    source_path: source.source_path,
    heading: 'Are Agent Harnesses Bringing Back Vibe Coding?',
    role: 'linked_source',
    excerpt: sourceExcerpt,
    linked_sources: [],
  },
];
if (evidence.some((entry) => entry.excerpt.length === 0 || entry.excerpt.length > MAX_EXCERPT_CHARS_PER_PAGE)) {
  return fail('EXCERPT_BOUND_EXCEEDED', `Every excerpt must contain 1-${MAX_EXCERPT_CHARS_PER_PAGE} characters.`);
}
const packet = {
  schema: 'uranus-evidence-packet-1',
  question: EXPECTED_QUESTION,
  selection_method: 'frozen_index_and_link_route',
  control_trace: [
    { sequence: 1, operation: 'read_kb_page', kb_path: 'index.md', role: 'navigation_locator' },
    { sequence: 2, operation: 'find_kb_pages', method: 'keyword_literal', query: 'dumb zone', candidates: ['concepts/context-rot.md'], role: 'candidate_locator' },
    { sequence: 3, operation: 'read_kb_page', kb_path: EXPECTED_PATHS[0], role: 'canonical_concept' },
    { sequence: 4, operation: 'read_kb_page', kb_path: EXPECTED_PATHS[1], role: 'linked_source' },
  ],
  route: EXPECTED_PATHS,
  evidence,
  limits: { max_pages: MAX_PAGES, max_excerpt_chars_per_page: MAX_EXCERPT_CHARS_PER_PAGE, max_packet_chars: MAX_PACKET_CHARS },
};
const packetJson = JSON.stringify(packet, null, 2);
if (packetJson.length > MAX_PACKET_CHARS) return fail('PACKET_BOUND_EXCEEDED', `The evidence packet exceeds the ${MAX_PACKET_CHARS}-character limit.`);
const modelPrompt = `You are Miranda. Answer the exact question using only the validated evidence packet below.\n\nRequirements:\n- Explain the phrase directly and concisely.\n- Support every material claim with packet evidence; do not add model knowledge.\n- Cite only kb_path values present in packet.evidence.\n- Preserve the linked source provenance.\n- End with a Sources section containing the exact cited kb_path values as Markdown bullets.\n- If the packet is insufficient, say so instead of guessing.\n\nQuestion:\n${EXPECTED_QUESTION}\n\nValidated evidence packet:\n${packetJson}`;
return [{ json: {
  status: 'success',
  question: EXPECTED_QUESTION,
  selection_method: packet.selection_method,
  evidence_packet: packet,
  evidence_packet_json: packetJson,
  packet_characters: packetJson.length,
  evidence_paths: EXPECTED_PATHS,
  model_prompt: modelPrompt,
  _packet_ready: true,
} }];

const packetResult = $('Assemble bounded evidence packet').first().json;
const modelResult = $input.first().json;
const answer = typeof modelResult.text === 'string' ? modelResult.text : (typeof modelResult.output === 'string' ? modelResult.output : null);
if (!answer) {
  return [{ json: { status: 'error', error_code: 'MODEL_OUTPUT_MISSING', message: 'The one-call model node did not return a text answer.' } }];
}
return [{ json: {
  status: 'success',
  question: packetResult.question,
  selection_method: packetResult.selection_method,
  model: 'models/gemini-3.5-flash',
  expected_model_actions_on_success: 1,
  packet_characters: packetResult.packet_characters,
  evidence_paths: packetResult.evidence_paths,
  answer,
  measurement_note: 'Confirm the single Gemini action and provider token usage from this n8n execution trace.',
} }];

const current = $input.first().json;
return [{ json: {
  status: 'error',
  error_code: current.error_code ?? 'PILOT_VALIDATION_FAILED',
  message: current.message ?? 'The one-call pilot stopped before Gemini because deterministic validation failed.',
  expected_question: current.expected_question ?? null,
  received_question: current.received_question ?? null,
  model_called: false,
} }];
